# precision = confirmed_valid / (confirmed_valid + false_positive)
# action_rate = implemented / surfaced
# recall must come from a golden benchmark or sampled human audits

alpha = defaultdict(lambda: 2.0)
beta = defaultdict(lambda: 1.0)

for v in verdicts:
    bucket = (v.rule_id or v.category, v.language)
    if v.final_outcome == 'accepted':
        alpha[bucket] += 1
    elif v.final_outcome == 'false_positive':
        beta[bucket] += 1
    elif v.final_outcome == 'rejected':
        beta[bucket] += 0.5  # ambiguous: penalize less than explicit false positive

for bucket in buckets_with_enough_samples(min_n=20):
    precision_posterior = alpha[bucket] / (alpha[bucket] + beta[bucket])
    if precision_posterior < 0.70 or revert_rate(bucket) > 0.15 or repeat_after_dismissal(bucket) > 0.10:
        raise_threshold(bucket)
    elif precision_posterior > 0.88 and benchmark_recall(bucket) < 0.60:
        lower_threshold(bucket)
    else:
        keep_threshold(bucket)
